(()=>{if(!document.getElementById('list-rows'))return;const s=Eam.s;let selected;const dialog=document.getElementById('task-reassign-dialog');function reassign(t){selected=t;Eam.text('reassign-task-info',t.id+' / 当前执行人 '+EamDomain.personName(t.assignee));const select=document.getElementById('reassign-person');select.replaceChildren(new Option('请选择具体执行人',''));for(const id of t.assignmentSnapshot?.resolvedPeople||[t.assignee])if(id!==t.assignee)select.add(new Option(EamDomain.personName(id),id));document.getElementById('reassign-reason').value='';Eam.text('reassign-error','');dialog.showModal();}document.getElementById('reassign-close').onclick=()=>dialog.close();document.getElementById('reassign-save').onclick=()=>{if(Eam.run('reassignTask',{id:selected.id,assignee:Eam.value('reassign-person'),reason:Eam.value('reassign-reason'),revision:selected.revision||1}))location.reload();else Eam.text('reassign-error',document.getElementById('toast')?.textContent||'');};EamList([s.task,...s.taskInstances].map(t=>({equipmentId:t.equipmentId||'EQ-001',status:t.status,person:t.assignee,values:[t.id,'1#混合机 / '+t.window,EamDomain.personName(t.assignee),t.snapshot.revision,EamProduct.label(t.status)],page:'inspection',query:{task:t.id},actions:Eam.can(['engineer','supervisor'])?[{label:'改派',disabled:t.status!=='pending'||(t.assignmentSnapshot?.resolvedPeople||[t.assignee]).length<2,run:()=>reassign(t)}]:[]})),{primary:'维护生成计划',page:'plan-list',mine:true});})();
